import requests
import logging

def task_func(repo_url: str) -> dict:
    if not repo_url:
        raise requests.exceptions.RequestException("URL cannot be empty.")

    try:
        response = requests.get(repo_url, timeout=10)
        response.raise_for_status()
        repo_data = response.json()

        if repo_data.get('open_issues_count', 0) > 1000:
            logging.warning(f"Repository {repo_url} has a high number of open issues.")

        return repo_data

    except requests.exceptions.HTTPError as e:
        if response.status_code == 403 and 'X-RateLimit-Remaining' in response.headers and response.headers['X-RateLimit-Remaining'] == '0':
            raise requests.exceptions.HTTPError("GitHub API rate limit exceeded.")
        raise e
    except requests.exceptions.RequestException as e:
        raise e

import json
import requests
import chardet

API_URL = "http://api.example.com/data"

def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content

    if not content:
        return {}

    encoding = from_encoding
    if not encoding:
        detected = chardet.detect(content)
        encoding = detected.get('encoding')

    if not encoding:
        raise ValueError("Unable to detect encoding for non-empty content")

    decoded_content = content.decode(encoding)
    reencoded_content = decoded_content.encode(to_encoding)

    return json.loads(reencoded_content.decode(to_encoding))

import ast
import requests
from bs4 import BeautifulSoup

def task_func(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except (requests.RequestException, ValueError):
        return []

    soup = BeautifulSoup(response.text, 'html.parser')
    scripts = soup.find_all('script')
    results = []

    for script in scripts:
        content = script.string
        if content:
            try:
                data = ast.literal_eval(content.strip())
                if isinstance(data, dict):
                    results.append(data)
            except (ValueError, SyntaxError, MemoryError):
                continue

    return results

